    let temp = text.split(" ");
  let i = 0;
  while(i < temp.length){
    if(temp[i] == "")
      temp.splice(i, 1);
    else i++;
  }
  let j = 0;
  while(j < temp.length - 1){
    if(temp[j].length == 0){
      temp.splice(j, 1);
    }else j++;
  }
