const isNested = (string) => {
    let leftBrackets = 0;
    let rightBrackets = 0;
    let hasNested = false;
    let hasError = false;
    for(let i = 0; i < string.length; i++){
        let currentBracket = string[i];
        if(currentBracket === '['){
            leftBrackets++;
        }
        if(currentBracket === ']'){
            rightBrackets++;
        }
        if(leftBrackets < rightBrackets){
            hasError = true;
        }
        if(leftBrackets > rightBrackets){
            hasNested = true;
        }
    }
    return hasNested && !hasError;
}

