const splitWords = (txt) => {
    if (/\s/.test(txt)) {
        let res = txt.split(" ");
        return res;
    } else if (/\,/.test(txt)) {
        let res = txt.split(",");
        return res;
    } else {
        let count = 0;
        let arr = [...txt];
        for (let i = 0; i < arr.length; i++) {
            if (arr[i].charCodeAt(0) % 2 !== 0) {
                count++;
            }
        }
        return count;
    }
}

