    if (paren_string === '') {
        return [];
    }
    if (paren_string.match(/[^()]/)) {
        throw new Error('Invalid characters passed to separate_paren_groups()');
    }
    var groups = [];
    var group = '';
    var is_in_group = false;
    for (var i = 0; i < paren_string.length; i++) {
        var paren = paren_string[i];
        if (paren === '(') {
            if (is_in_group) {
                group += paren;
            } else {
                is_in_group = true;
                group = paren;
            }
        } else if (paren === ')') {
            if (is_in_group) {
                group += paren;
                groups.push(group);
                is_in_group = false;
            } else {
                throw new Error('Unbalanced right parenthesis at index ' + i);
            }
        }
    }
    if (is_in_group) {
        throw new Error('Unbalanced left parenthesis at index ' + i);
    }
    return groups;
}

