    var counter = 0;
    var target = '';
    var multi = [];
    var howMany = 0;
    var winner = '';
    var letters = test.split(' ');
    for(var i = 0; i < letters.length; i++){
        alphabet[letters[i]] = alphabet[letters[i]] ? alphabet[letters[i]]+1 : 1;
    }
    for(var letter in alphabet){
        counter = alphabet[letter];
        if(counter >= howMany){
            target = letter;
            howMany = counter;
        }
    }
    for(var letter in alphabet){
        if(alphabet[letter] == howMany){
            multi.push(letter);
        }
    }
    if(multi.length > 1){
        for(var i = 0; i < multi.length; i++){
            winner += multi[i];
            if(i != multi.length-1){
                winner += ' ';
            }
        }
        return {winner: howMany};
    }else{
        return {target: howMany};
    }
}

