        let testDict = {}
        let maxValue = 0;
        let highestValueArray = [];
        for(let i = 0; i < testArray.length; i++){
            let indexElement = testArray[i];
            if(testDict[indexElement] == undefined){
                testDict[indexElement] = 1;
            }
            else{
                testDict[indexElement] += 1;
            }
        }
        let testDictKeys = Object.keys(testDict);
        for(let i = 0; i < testDictKeys.length; i++){
            let indexKey = testDictKeys[i];
            if(testDict[indexKey] > maxValue){
                maxValue = testDict[indexKey];
                highestValueArray = [indexKey];
            }
            else if(testDict[indexKey] == maxValue){
                highestValueArray.push(indexKey);
            }
        }
        let keyToReturn = {};
        for(let i = 0; i < highestValueArray.length; i++){
            let indexKey = highestValueArray[i];
            keyToReturn[indexKey] = maxValue;
        }
        return keyToReturn;
    }
}

