    if(test == ''){
        return {};
    }
    let maxCount = 1;
    let result = {};
    let arr = test.split(' ');
    let testMap = new Map();
    for(let i = 0; i < arr.length; i++){
        if(testMap.has(arr[i])){
            testMap.set(arr[i], testMap.get(arr[i]) + 1);
        }
        else{
            testMap.set(arr[i], 1);
        }
    }
    for(let item of testMap){
        if(item[1] >= maxCount){
            maxCount = item[1];
        }
    }
    for(let item of testMap){
        if(item[1] == maxCount){
            result[item[0]] = item[1];
        }
    }
    return result;
}

